// sdk/mcp/tools.js — the MCP tool registry for MAAC Go Email.
//
// One registry, every surface:
//   - api/mcp.js                         Streamable HTTP at /api/mcp
//   - sdk/mcp/bin/maacgo-email-mcp.js    stdio, shipped as @maacgo/email-mcp
//   - .well-known/mcp/server-card.json   generated by sdk/mcp/scripts/build-server-card.mjs
//
// Every handler calls the public REST API with the caller's own API key, so
// scopes, quota, the wallet and the suppression list all apply exactly as they
// would to a direct fetch. There is no privileged path here.

export const SERVER_NAME = 'maacgo-email';
export const SERVER_TITLE = 'MAAC Go Email';
export const SERVER_VERSION = '0.3.0';
export const PUBLIC_SITE = 'https://edm.cresclab.com';
export const MCP_URL = PUBLIC_SITE + '/api/mcp';
export const DOCS_URL = PUBLIC_SITE + '/mcp';
// Oldest last. The server answers with the client's version when it is one of
// these, otherwise with the first.
export const PROTOCOL_VERSIONS = ['2025-06-18', '2025-03-26', '2024-11-05'];

const DEFAULT_BASE_URL = PUBLIC_SITE + '/api';

export function makeClient({ apiKey, baseUrl = DEFAULT_BASE_URL, fetch: fetchImpl = globalThis.fetch } = {}) {
  if (!apiKey) throw new Error('apiKey_required');
  const base = String(baseUrl || DEFAULT_BASE_URL).replace(/\/+$/, '');
  return async function call(method, path, body) {
    const r = await fetchImpl(base + path, {
      method,
      headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + apiKey },
      body: body ? JSON.stringify(body) : undefined,
    });
    const ct = r.headers.get('content-type') || '';
    const data = ct.includes('json') ? await r.json() : await r.text();
    if (!r.ok) {
      const err = new Error(data?.error || 'http_' + r.status);
      err.status = r.status;
      err.data = data;
      throw err;
    }
    return data;
  };
}

// ---- schema pieces ---------------------------------------------------------

const id = (what) => ({ type: 'string', pattern: '^[0-9]+$', description: what });
const NO_ARGS = { type: 'object', properties: {} };

const segment = (description, { allowNone = false } = {}) => ({
  type: 'object',
  description,
  properties: {
    type: {
      type: 'string',
      enum: [...(allowNone ? ['none'] : []), 'all', 'tag', 'engaged', 'never_engaged'],
      description: '"all" = every contact; "tag" = contacts carrying `tag`; "engaged" = ever opened or clicked; "never_engaged" = never opened or clicked' + (allowNone ? '; "none" = leave nobody out.' : '.'),
    },
    tag: { type: 'string', description: 'The tag, when type is "tag".' },
  },
  required: ['type'],
});

// MCP tool annotations. Hints only — the REST API enforces the real rules.
const READ = { readOnlyHint: true, destructiveHint: false, idempotentHint: true, openWorldHint: false };
const write = (o = {}) => ({ readOnlyHint: false, destructiveHint: false, idempotentHint: false, openWorldHint: false, ...o });

const toolError = (code) => Object.assign(new Error(code), { data: { error: code } });

