export const TOOL_BY_NAME = Object.fromEntries(TOOLS.map((t) => [t.name, t]));

// What a client sees in tools/list (and the server card): MCP field names only.
// requiredScopes and handler stay server-side.
export function publicTool(t) {
  return {
    name: t.name,
    title: t.title,
    description: t.description,
    inputSchema: t.inputSchema,
    annotations: { title: t.title, ...t.annotations },
  };
}

// Required arguments are checked before any network call, and reported as a
// tool error the model can read and correct (not a protocol error).
export function missingArgs(tool, args) {
  const a = args && typeof args === 'object' && !Array.isArray(args) ? args : {};
  return (tool.inputSchema.required || []).filter((k) => a[k] === undefined || a[k] === null || a[k] === '');
}

// What every MCP client is told at initialize. Tool descriptions are read
// per call; this is the one place to say something about the key itself.
export const SERVER_INSTRUCTIONS = [
  'MAAC Go Email: transactional email, campaigns and contacts for one account, authenticated by the API key in use.',
  'Keys come in two modes and the mode is in the prefix. sk_live_ keys deliver mail. sk_test_ keys only RECORD a message: send_email returns 202 with status "sent" and test_mode:true, but nothing reaches any inbox and nothing is charged.',
  'Before telling a user an email "was sent", check test_mode on the result (or call get_me and read key_mode). If it is a test key and they expect delivery, tell them to create an sk_live_ key at https://edm.cresclab.com/developers.',
  'For any email sent more than once, create_template once and then send_email with template_id + variables, rather than inlining HTML on every call.',
  'Test keys never deliver: send_email records the message without sending it, and send_campaign refuses a test key.',
  'For a campaign, run estimate_campaign before send_campaign and tell the user the recipient count. If a send is refused for credit, show the top-up link from the error.',
].join(' ');

export function toMcpToolResult(result) {
  let text = typeof result === 'string' ? result : JSON.stringify(result, null, 2);
  // A test-key send comes back "sent". Without this line every model read
  // that as delivered — the first outside tester did.
  if (result && typeof result === 'object' && result.test_mode === true && result.status) {
    text += '\n\nNOT DELIVERED: this API key is sk_test_, so the message was only recorded. No email reached ' + (result.to || 'the recipient') + ' and nothing was charged. To deliver for real, create an sk_live_ key at https://edm.cresclab.com/developers and use that instead.';
  }
  return { content: [{ type: 'text', text }] };
}

export function formatToolError(name, e) {
  const code = e?.data?.error || e?.message || 'error';
  const hint = {
    unauthorized: 'The API key is missing, revoked, or lacks the scope this tool needs.',
    insufficient_credit: 'The free allowance is used up and the prepaid wallet cannot cover this. Top up at https://edm.cresclab.com/settings#billing',
    daily_cap_exceeded: 'The daily send cap has been reached. It resets at midnight.',
    suppressed: 'That address unsubscribed, bounced or complained, so it cannot be mailed.',
    account_frozen: 'Sending is paused on this account.',
    template_not_found: 'No stored template has that id on this account. Call list_templates to see them, or create_template to make one.',
    template_name_taken: 'A template with that name already exists — use its id, or update_template.',
    too_many_templates: 'This account already holds 100 templates. Delete one first.',
    missing_body: 'Pass html or text, or a template_id.',
    missing_subject: 'Pass a subject, or a template_id whose template has one.',
    invalid_to: 'The `to` address is not a valid email address.',
    invalid_email: 'That is not a valid email address.',
    not_found: 'Nothing with that id on this account.',
    contact_limit: 'The plan\'s contact allowance is full. Upgrade in Settings → Billing at https://edm.cresclab.com/settings#billing',
    bad_op: 'op must be "tag" or "untag". This tool cannot delete contacts.',
    no_ids: 'Pass at least one contact id from list_contacts.',
    already_sent: 'This campaign has already been sent.',
    already_sending: 'This campaign is already sending.',
    approval_required: 'This workspace requires approval before a campaign is sent. Ask an admin to approve it in the editor.',
    no_recipients: 'The campaign\'s audience reaches nobody. Check it with estimate_campaign.',
    test_key_cannot_send_campaign: 'This is a test key (sk_test_…). Test keys never deliver, so they cannot send campaigns. Use a live key, or send it from the console.',
  }[code];
  // The rest of the error body (prices, limits, detail) is what lets the model
  // explain a refusal instead of guessing at it.
  const extra = e?.data && typeof e.data === 'object' ? Object.fromEntries(Object.entries(e.data).filter(([k]) => k !== 'error')) : {};
  return `${name} failed: ${code}${hint ? ' — ' + hint : ''}${Object.keys(extra).length ? '\n' + JSON.stringify(extra) : ''}`;
}
